DO $policy$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='contas_bancarias' AND policyname='contador read bancos') THEN EXECUTE 'CREATE POLICY "contador read bancos" ON public."contas_bancarias" AS PERMISSIVE FOR SELECT TO "authenticated" USING (has_role(auth.uid(), ''contador''::app_role))'; END IF; END $policy$;
DO $policy$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='caixa_sessoes' AND policyname='caixa staff') THEN EXECUTE 'CREATE POLICY "caixa staff" ON public."caixa_sessoes" AS PERMISSIVE FOR ALL TO "authenticated" USING ((has_role(auth.uid(), ''admin''::app_role) OR has_role(auth.uid(), ''financeiro''::app_role))) WITH CHECK ((has_role(auth.uid(), ''admin''::app_role) OR has_role(auth.uid(), ''financeiro''::app_role)))'; END IF; END $policy$;
