DO $policy$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='pontos' AND policyname='pontos insert') THEN EXECUTE 'CREATE POLICY "pontos insert" ON public."pontos" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((has_role(auth.uid(), ''admin''::app_role) OR has_role(auth.uid(), ''financeiro''::app_role) OR ((user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM funcionarios f
  WHERE ((f.id = pontos.funcionario_id) AND (f.user_id = auth.uid())))))))'; END IF; END $policy$;
