DO $policy$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='pedido_item_componentes' AND policyname='pedido_item_componentes_select') THEN EXECUTE 'CREATE POLICY "pedido_item_componentes_select" ON public."pedido_item_componentes" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM (pedido_itens i
     JOIN pedidos p ON ((p.id = i.pedido_id)))
  WHERE ((i.id = pedido_item_componentes.pedido_item_id) AND ((p.user_id = auth.uid()) OR (p.motoboy_id = auth.uid()) OR has_role(auth.uid(), ''admin''::app_role) OR has_role(auth.uid(), ''atendente''::app_role) OR has_role(auth.uid(), ''producao''::app_role))))))'; END IF; END $policy$;
